const convs = $input.first().json.data?.payload || [];
const ag = $('Agentes online').first().json.availableAgents || [];
if (!ag.length) {
  throw new Error('No hay agentes online en el inbox; no se puede asignar la conversación.');
}
const r = ag.map(a => ({ agentId: a.id, c: convs.filter(v => v.meta?.assignee?.id === a.id).length }));
let m = r[0];
for (const x of r) { if (x.c < m.c) m = x; }
return [{ json: { agentId: m.agentId } }];

