const id = $json.id;
if (id === undefined || id === null || id === '') {
  throw new Error('Chatwoot no devolvió el id de la conversación. Respuesta: ' + JSON.stringify($json));
}
return { json: { conversation_id: String(id), phone: $('Webhook entrada').item.json.body.data.key.remoteJid.split('@')[0] } };

const body = $('Webhook entrada').item.json.body || {};
const data = body.data || {};
const m = (data.message && data.message.deviceSentMessage && data.message.deviceSentMessage.message)
          || data.message || {};
const live = m.liveLocationMessage || null;
const stat = m.locationMessage || null;
const loc  = live || stat;
if (!loc) { return { esUbicacion: false, valida: false }; }
const lat = loc.degreesLatitude;
const lng = loc.degreesLongitude;
// Validacion: deben existir, ser numeros, estar en rango y no ser 0,0
const valida = (typeof lat === 'number' && typeof lng === 'number') &&
               !Number.isNaN(lat) && !Number.isNaN(lng) &&
               Math.abs(lat) <= 90 && Math.abs(lng) <= 180 &&
               !(lat === 0 && lng === 0);
const cliente = ((data.key && data.key.remoteJid) || '').split('@')[0];
const mapsUrl = `https://www.google.com/maps?q=${lat},${lng}`;
return {
  esUbicacion: true, valida, enVivo: !!live,
  lat, lng, cliente, mapsUrl,
  nombre: loc.name || '', direccion: loc.address || '',
  keyId: (data.key && data.key.id) || null,
  secuencia: live ? (live.sequenceNumber || null) : null
};

const n = $('Normalizar ubicacion').item.json;
const g = $json || {};
const addr = (g && g.address) || {};
const departamento = addr.state || '';
const municipio = addr.municipality || addr.city || addr.town || addr.county || addr.village || addr.suburb || '';
const display = g.display_name || '';
const lugar = [municipio, departamento].filter(Boolean).join(', ');
const tipoTxt = n.enVivo ? 'su ubicacion EN TIEMPO REAL' : 'su ubicacion ACTUAL';
const extra = [n.nombre, n.direccion].filter(Boolean).join(' - ');
const contenido = (`📍 El cliente compartio ${tipoTxt}. ` +
  (extra ? extra + '. ' : '') +
  (lugar ? `Lugar: ${lugar}. ` : '') +
  (display ? `Direccion aprox.: ${display}. ` : '') +
  `Coordenadas: ${n.lat}, ${n.lng}. Ver en el mapa: ${n.mapsUrl}`)
  .replace(/\n/g,' ').replace(/\r/g,' ').replace(/\t/g,' ').replace(/"/g,' ');
return { cliente:n.cliente, lat:n.lat, lng:n.lng, enVivo:n.enVivo,
         mapsUrl:n.mapsUrl, departamento, municipio, contenido };

const estado = String($('Obtener estado').item.json.paso ?? '');
if (estado === '1000') {
  return { json: { reutiliza: false, id: null } };
}

const inbox = Number($('Variables del menú').item.json.inbox_id);
const resp = $json || {};
let convs = resp.payload || (resp.data && resp.data.payload) || [];
if (!Array.isArray(convs)) convs = [];

const abierta = convs.find(c =>
  Number(c.inbox_id) === inbox &&
  (c.status === 'open' || c.status === 'pending')
);

if (abierta) {
  return { json: { reutiliza: true, id: abierta.id } };
}
return { json: { reutiliza: false, id: null } };

